#include <iostream>

using namespace std;

int main() {
    int initial_gum = 20;
    int school_hours = 8;
    int gum_per_hour = 1 / 2; // Chew 1 piece every 2 hours
    int gum_chewed_school = school_hours * gum_per_hour;
    int gum_chewed_home = 1;
    int gum_chewed_dinner = 1;
    int gum_total_chewed = gum_chewed_school + gum_chewed_home + gum_chewed_dinner;
    int gum_remaining = initial_gum - gum_total_chewed;
    int gum_given_sister = gum_remaining / 2;
    int gum_left = gum_remaining - gum_given_sister;

    cout << gum_left << endl;

    return 0;
}
